let LANG="en";
function t(key,vars){
  let s=(I18N[LANG]&&I18N[LANG][key]);if(s==null)s=I18N.en[key];if(s==null)return key;
  if(typeof s==="object"){const n=vars&&vars.n;let cat="other";try{cat=new Intl.PluralRules(LANG).select(n);}catch(e){}s=s[cat]??s.other??I18N.en[key].other;}
  if(vars)s=s.replace(/\{(\w+)\}/g,(m,k)=>vars[k]!=null?vars[k]:m);
  if(LANG==="ar")s=s.replace(/(\d+) دقيقة/g,(m,d)=>{const n=+d;
    if(n===1)return "دقيقة واحدة";if(n===2)return "دقيقتان";if(n>=3&&n<=10)return d+" دقائق";return m;});
  return s;
}



