function segPts(a,b){
  const k=a+"|"+b;if(BENDS[k])return BENDS[k];
  const r=BENDS[b+"|"+a];return r?r.slice().reverse():[];
}
function chainPts(ids){
  const out=[[ST[ids[0]].x,ST[ids[0]].y]];
  for(let i=1;i<ids.length;i++){segPts(ids[i-1],ids[i]).forEach(p=>out.push(p));out.push([ST[ids[i]].x,ST[ids[i]].y]);}
  return out;
}
// polyline with rounded corners
function roundD(P,R){
  const q=[P[0]];for(let i=1;i<P.length;i++){const a=q[q.length-1],b=P[i];if(Math.abs(a[0]-b[0])>.01||Math.abs(a[1]-b[1])>.01)q.push(b);}
  if(q.length<2)return "";
  let d=`M${q[0][0]},${q[0][1]}`;
  for(let i=1;i<q.length-1;i++){
    const [ax,ay]=q[i-1],[bx,by]=q[i],[cx,cy]=q[i+1];
    const l1=Math.hypot(bx-ax,by-ay),l2=Math.hypot(cx-bx,cy-by);
    const cross=Math.abs((bx-ax)*(cy-by)-(by-ay)*(cx-bx));
    if(cross<1e-6){d+=`L${bx},${by}`;continue;}
    const r=Math.min(R,l1/2,l2/2);
    const p1=[bx-(bx-ax)/l1*r,by-(by-ay)/l1*r],p2=[bx+(cx-bx)/l2*r,by+(cy-by)/l2*r];
    d+=`L${p1[0].toFixed(1)},${p1[1].toFixed(1)}Q${bx},${by} ${p2[0].toFixed(1)},${p2[1].toFixed(1)}`;
  }
  const z=q[q.length-1];return d+`L${z[0]},${z[1]}`;
}
const lineD=ids=>roundD(chainPts(ids),22);


